P = [
 dict(pmid='43039175', doi='10.1016/j.envres.2026.126204', journal='Environ Res', title='Exposure to Fine Particulate Matter During Pregnancy and Postpartum Psychological Functioning in the ECHO Cohort: Effect Modification by Body Mass Index.', short='ECHO 18-site US pregnancy PM2.5 postpartum EPDS anhedonia BMI effect modification DLM', design='Prospective cohort', pm='Daily residential PM2.5 from a validated satellite-based spatiotemporal hybrid model over the pregnancy residential history', geo='United States (18 ECHO sites)', endpoint='Edinburgh Postnatal Depression Scale total, anhedonia and depressive subscales within 1 y of delivery', tier='B', basis='Satellite-fused', affil='Icahn School of Medicine at Mount Sinai, USA; not stated in record', n='6,407 pregnant women from 18 ECHO sites; residential PM2.5 from a satellite-based hybrid model, EPDS completed within a year of delivery, analysed with GAMs, distributed lag models and trimester windows. Main-effect models found no overall PM2.5-EPDS association. Thin-plate GAMs suggested a nonlinear PM2.5 x pre-pregnancy BMI interaction for the anhedonia subscale (interaction p=0.06), with positive associations at higher BMI, strongest for first-trimester exposure; DLM cumulative estimates agreed. No effect sizes or CIs are given in the abstract. The headline is a borderline interaction from a two-dimensional smooth after a null main effect, with multiple windows and three outcomes, so it is hypothesis-generating at best. Relevance: indirect - modelled exposure with no measurement contribution; susceptibility-by-BMI framing could inform targeted personal monitoring.', sub=corpus.NEU),
 dict(pmid='43037792', doi='10.1007/s12012-026-10186-9', journal='Cardiovasc Toxicol', title='Cardiac Rhythm Disorders and Chronic Occupational Exposure to Pollutants: A Systematic Review.', short='Toulouse systematic review occupational pollutants arrhythmia atrial fibrillation lead CS2 solvents inhalable particles', design='Systematic review', pm='Occupational inhalable particles among metals, solvents, gases and pesticides; exposure metrics as reported by 21 primary studies', geo="Global / multi-region", endpoint='Cardiac arrhythmia, including atrial fibrillation', tier='C', basis='Review / no primary exposure', affil='Toulouse-Purpan University Hospital, France; Toulouse-Purpan University Hospital, France', n="Systematic review of 21 studies on chronic occupational exposure (metals, solvents, aldehydes, amines, cyanides, plastics, acids, gases, pesticides) and cardiac arrhythmia. Lead, carbon disulfide, certain solvents and inhalable particles were associated with arrhythmias, chiefly atrial fibrillation; oxidative stress, cytotoxicity and inflammation are proposed as mechanisms. No pooled estimate, risk-of-bias grading or particle size fraction is reported in the abstract, so the particle signal cannot be separated from co-exposures in the source workplaces. Metadata gives no search dates or databases beyond 'several'. Relevance: low - occupational particle exposure is mentioned but not quantified; wearable PM monitoring in factories is the obvious missing exposure layer.", sub=corpus.OCC),
 dict(pmid='43036120', doi='10.4046/trd.2026.0134', journal='Tuberc Respir Dis (Seoul)', title='Indoor Air Quality Management for Patients with COPD and IPF: Practical Recommendations Based on Current Standards and Evidence.', short='Korea narrative review indoor air quality management COPD IPF nine-parameter action references', design='Narrative review', pm='Indoor PM2.5 and PM10 alongside NO2, CO2, formaldehyde, TVOC, CO, O3 and relative humidity; reference values from national and international standards', geo='Republic of Korea', endpoint='Practical IAQ action references and maintenance targets for COPD and IPF patients', tier='C', basis='Review / no primary exposure', affil='Yonsei University, Republic of Korea; Yonsei University College of Medicine, Republic of Korea', n="Focused narrative review proposing residential indoor air quality management rules for patients with COPD and idiopathic pulmonary fibrosis. Nine parameters were selected (PM2.5, PM10, NO2, CO2, formaldehyde, TVOC, CO, O3, relative humidity), each with an action reference and a maintenance target that keep the source standard's averaging time; ambient forecast categories are used only for outdoor-driven pollutants. Recommendations: source control, forecast-guided ventilation, particle filtration and cooking/combustion control. The thresholds are explicitly not disease-specific clinical cut-offs, and no new exposure-response evidence is presented. Relevance: moderate - the framework presumes a home monitor reporting PM2.5 and PM10 at standard averaging times, exactly the use case for consumer-grade sensors, whose bias at high humidity is not addressed.", sub=corpus.OCC),
 dict(pmid='43036397', doi='10.1177/11786302261493677', journal='Environmental health insights', title='Mortality and Health Losses From Diseases Attributable to Air Pollution in Ethiopia, From 1990 to 2023.', short='GBD 2023 Ethiopia national subnational air pollution deaths DALYs ambient PM household solid fuel 1990-2023', design='Burden of disease (GBD)', pm='GBD 2023 ambient PM2.5 and household air pollution from solid fuels exposure estimates', geo='Ethiopia', endpoint='Deaths, YLDs, YLLs and DALYs attributable to air pollution', tier='B', basis='Model (CTM / LUR / ML)', affil='Adigrat University, Ethiopia; Bule Hora University, Ethiopia', n="GBD 2023 secondary analysis for Ethiopia, national and subnational, 1990-2023. In 2023 air pollution was attributed 139 deaths per 100,000 (95% UI 106-177), 4,286 YLLs (3,475-5,107) and 4,557 DALYs per 100,000 (3,685-5,397); YLDs were driven by household solid fuels (247 per 100,000, UI 152-344). Addis Ababa had the highest ambient PM mortality (64 per 100,000, UI 43-88) and the lowest household air pollution mortality; Afar had the highest overall mortality (185, UI 137-232). Mortality rates were flat across 33 years while DALY rates fell. Every number inherits GBD's exposure surface, which in Ethiopia rests on very few ground monitors; the subnational contrasts are model outputs, not observations. Relevance: high in principle - Ethiopia is a textbook case where a low-cost network would constrain the ambient surface the burden depends on.", sub=corpus.BURD),
]
